import java.util.*;

class Solution {
    public int countLandMasses(char[][] grid) {
        int r = grid.length, c = grid[0].length, count = 0;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++) {
                if (grid[i][j] != '1') continue;
                count++; // new land mass found
                grid[i][j] = '0';
                stack.push(new int[]{i, j});
                while (!stack.isEmpty()) { // sink the whole land mass
                    int[] cur = stack.pop();
                    for (int[] d : dirs) {
                        int x = cur[0] + d[0], y = cur[1] + d[1];
                        if (x >= 0 && y >= 0 && x < r && y < c && grid[x][y] == '1') {
                            grid[x][y] = '0';
                            stack.push(new int[]{x, y});
                        }
                    }
                }
            }
        return count;
    }
}

