class Solution:
    def countLandMasses(self, grid: List[List[str]]) -> int:
        r, c = len(grid), len(grid[0]); seen = set(); cnt = 0
        for i in range(r):
            for j in range(c):
                if grid[i][j] == "1" and (i, j) not in seen:
                    cnt += 1; seen.add((i, j)); st = [(i, j)]
                    while st:
                        a, b = st.pop()
                        for x, y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                            if 0 <= x < r and 0 <= y < c and grid[x][y] == "1" and (x, y) not in seen:
                                seen.add((x, y)); st.append((x, y))
        return cnt

