function countLandMasses(grid) {
  const r = grid.length, c = grid[0].length, seen = grid.map(x => x.map(() => false)); let cnt = 0;
  for (let i = 0; i < r; i++) for (let j = 0; j < c; j++) if (grid[i][j] === "1" && !seen[i][j]) {
    cnt++; seen[i][j] = true; const st = [[i, j]];
    while (st.length) {
      const [a, b] = st.pop();
      for (const [x, y] of [[a+1,b],[a-1,b],[a,b+1],[a,b-1]])
        if (x >= 0 && x < r && y >= 0 && y < c && grid[x][y] === "1" && !seen[x][y]) { seen[x][y] = true; st.push([x, y]); }
    }
  }
  return cnt;
}
